{
  "items": [
    {
      "name": "Finsupp.sum_option_index",
      "module_name": "Mathlib.Data.Finsupp.Option",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_2} {N : Type u_3} [inst : AddZeroClass M] [inst_1 : AddCommMonoid N] (f : Option α →₀ M)\n  (b : Option α → M → N),\n  (∀ (o : Option α), b o 0 = 0) →\n    (∀ (o : Option α) (m₁ m₂ : M), b o (m₁ + m₂) = b o m₁ + b o m₂) →\n      f.sum b = b none (f none) + f.some.sum fun a => b (some a)"
    },
    {
      "name": "Finsupp.optionElim",
      "module_name": "Mathlib.Data.Finsupp.Option",
      "kind": "definition",
      "type": "{α : Type u_1} → {M : Type u_2} → [inst : Zero M] → M → (α →₀ M) → Option α →₀ M"
    },
    {
      "name": "Fintype.sum_option",
      "module_name": "Mathlib.Data.Fintype.BigOperators",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_4} [inst : Fintype α] [inst_1 : AddCommMonoid M] (f : Option α → M),\n  ∑ i, f i = f none + ∑ i, f (some i)"
    },
    {
      "name": "finsum_option",
      "module_name": "Mathlib.Algebra.BigOperators.Finprod",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_5} [inst : AddCommMonoid M] {f : Option α → M},\n  (Function.support (f ∘ some)).Finite → ∑ᶠ (o : Option α), f o = f none + ∑ᶠ (a : α), f (some a)"
    },
    {
      "name": "Finset.sum_insertNone",
      "module_name": "Mathlib.Algebra.BigOperators.Option",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_2} [inst : AddCommMonoid M] (f : Option α → M) (s : Finset α),\n  ∑ x ∈ Finset.insertNone s, f x = f none + ∑ x ∈ s, f (some x)"
    }
  ]
}
